const item = $input.first();
const source = item?.json ?? {};
let raw = String(source.output ?? '').trim();
raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
const fallback = 'Desculpe, não consegui preparar uma resposta confiável agora. Reformule a dúvida ou tente novamente em instantes, por favor.';
const internalMarker = /\b(?:the user (?:wrote|said|asked|sent)|okay,\s*the user|let me (?:check|think|see)|i need to|i should|we need to|my plan is|analysis\s*:|reasoning\s*:|chain of thought|step[- ]by[- ]step)\b/i;
const englishTokens = (raw.match(/\b(?:the|this|that|and|with|from|for|you|your|i|we|it|is|are|can|will|would|should|please|here|user|need|let|what|when|where|how|first|then|because)\b/gi) || []).length;
const portugueseTokens = (raw.match(/\b(?:de|da|do|das|dos|e|que|para|com|não|você|seu|sua|sobre|por|favor|tem|está|foi|são|precisa|posso|curso|agendamento|pedido|fatec)\b/gi) || []).length;
const looksLikeEnglish = englishTokens >= 3 && portugueseTokens < 3;
const finalText = !raw || internalMarker.test(raw) || looksLikeEnglish ? fallback : raw;

// Normalizar quebras de linha se o texto vier com sequências literais escapadas (\n)
let textToClean = finalText;
if (textToClean.includes('\\n') && !textToClean.includes('\n')) {
  textToClean = textToClean.replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n');
}

const clean = textToClean
  .replace(/\r\n?/g, '\n')
  .replace(/\x60\x60\x60[^\n]*\n?/g, '')
  .replace(/\x60\x60\x60/g, '')
  .replace(/!\[([^\]]*)\]\([^)]+\)/g, '$1')
  .replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, label, url) => label.trim() === url.trim() ? url.trim() : `${label.trim()} (${url.trim()})`)
  .replace(/^\s{0,3}#{1,6}\s+/gm, '')
  .replace(/^\s*>\s?/gm, '')
  .replace(/^\s*[-*+]\s+/gm, '• ')
  // Preserva negrito no padrão WhatsApp (*texto*) convertendo de markdown (**texto**)
  .replace(/\*\*([^\*\n]+)\*\*/g, '*$1*')
  .replace(/__([^\_\n]+)__/g, '_$1_')
  .replace(/~~(.*?)~~/g, '$1')
  .replace(/\x60([^\x60]+)\x60/g, '$1')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// WhatsApp suporta até 4.096 caracteres por mensagem.
// Mensagens normais dentro do limite devem seguir íntegras em mensagem única.
const MAX_LEN = 3500;
if (clean.length <= MAX_LEN) {
  return [{ json: { output: clean } }];
}

const chunks = [];
let current = '';

const pushCurrent = () => {
  if (current.trim()) chunks.push(current.trim());
  current = '';
};

// Divisão preservando parágrafos e quebras de linha
const paragraphs = clean.split('\n\n');
for (const para of paragraphs) {
  const trimmed = para.trim();
  if (!trimmed) continue;
  if (!current) {
    if (trimmed.length <= MAX_LEN) {
      current = trimmed;
    } else {
      for (const line of trimmed.split('\n')) {
        const tl = line.trim();
        if (!tl) continue;
        if (!current) {
          current = tl;
        } else if ((current + '\n' + tl).length <= MAX_LEN) {
          current += '\n' + tl;
        } else {
          pushCurrent();
          current = tl;
        }
      }
    }
  } else if ((current + '\n\n' + trimmed).length <= MAX_LEN) {
    current += '\n\n' + trimmed;
  } else {
    pushCurrent();
    if (trimmed.length <= MAX_LEN) {
      current = trimmed;
    } else {
      for (const line of trimmed.split('\n')) {
        const tl = line.trim();
        if (!tl) continue;
        if (!current) {
          current = tl;
        } else if ((current + '\n' + tl).length <= MAX_LEN) {
          current += '\n' + tl;
        } else {
          pushCurrent();
          current = tl;
        }
      }
    }
  }
}
pushCurrent();

return chunks.map(output => ({ json: { output } }));

/** Validação de produção do RAG: aceita mensagens diretas de qualquer contato e prepara chave atômica de deduplicação. */
const acceptedItems = [];
const now = Date.now();

if (!globalThis.__seenChatwootMessages) {
  globalThis.__seenChatwootMessages = new Map();
}
for (const [mid, ts] of globalThis.__seenChatwootMessages.entries()) {
  if (now - ts > 120000) {
    globalThis.__seenChatwootMessages.delete(mid);
  }
}

for (const item of $input.all()) {
  const root = item.json ?? {};
  const payload = root.body ?? root;
  const message = payload.message && typeof payload.message === 'object' ? payload.message : payload;
  const conversation = payload.conversation ?? message.conversation ?? {};
  const event = String(payload.event ?? '');
  const rawType = message.message_type ?? payload.message_type;
  const isIncoming = rawType === 'incoming' || rawType === 0 || rawType === '0';
  const privateValue = message.private ?? payload.private;
  const isPublic = privateValue === false || privateValue === 0 || String(privateValue).trim().toLowerCase() === 'false';
  const senderAttributes = conversation.meta?.sender?.custom_attributes ?? payload.sender?.custom_attributes ?? {};
  const chatId = String(senderAttributes.waha_whatsapp_chat_id ?? '').trim().toLowerCase();
  const isGroupChat = chatId.endsWith('@g.us');
  const conversationId = String(conversation.id ?? payload.conversation_id ?? '');
  const messageId = String(message.id ?? payload.id ?? '');
  const hasMessageIdentity = Boolean(conversationId && messageId);

  // Sem restrição de contato: aceita qualquer conversa/contato (apenas ignora grupos de WhatsApp se houver @g.us)
  const channelAllowed = !isGroupChat;

  if (event === 'message_created' && isIncoming && isPublic && channelAllowed && hasMessageIdentity) {
    if (globalThis.__seenChatwootMessages.has(messageId)) {
      continue;
    }
    globalThis.__seenChatwootMessages.set(messageId, now);
    acceptedItems.push({
      json: {
        ...root,
        dedupKey: 'chatwoot:msg:dedup:' + messageId
      }
    });
  }
}
return acceptedItems;

/** Deduplicação atômica via Redis: se count for 1, primeira chegada. Se > 1, descarta duplicata imediatamente. */
const items = $input.all();
const redisResult = items[0]?.json || {};
const count = Number(Object.values(redisResult)[0] || 0);

if (count === 1) {
  return [$('Validar evento, mensagem e atendimento humano').item];
}

// Duplicata concorrente (já em processamento pelo n8n) -> descarta sem prosseguir
return [];

/** Libera texto/transcrição normalizados e verifica o limite sobre conteúdo do usuário, sem contar metadados internos. */
const MAX_USER_TEXT_CHARS = 2000;
const LIMIT_REPLY = 'O texto recebido (mensagem, legenda ou transcrição) ultrapassa 2.000 caracteres. Envie um resumo ou apenas o trecho relevante, por favor.';
return $input.all().flatMap((item, index) => {
  const data = item.json ?? {};
  if (data.normalizationStatus !== 'ready') return [];
  const contentText = String(data.contentText ?? '').trim();
  if (!contentText) return [];
  const providedCount = Number(data.userTextChars);
  const charCount = Number.isFinite(providedCount) && providedCount >= 0 ? providedCount : Array.from(contentText).length;
  if (charCount <= MAX_USER_TEXT_CHARS) {
    return [{ json: { ...data, userTextChars: charCount, textLimitExceeded: false }, ...(item.binary ? { binary: item.binary } : {}), pairedItem: { item: index } }];
  }
  return [{ json: { textLimitExceeded: true, userTextChars: charCount, normalizationStatus: 'ready', output: LIMIT_REPLY }, pairedItem: { item: index } }];
});

const prev = $('Liberar conteúdo textual para o agente').item.json ?? {};
const docMeta = $('Verificar tipo de entrada e documentos').item.json ?? {};
let consolidated = {};
try { consolidated = $('Aplicar texto consolidado').item.json ?? {}; } catch {}
const text = String(consolidated.contentText ?? $json.contentText ?? prev.contentText ?? docMeta.contentText ?? '').trim();
const conversationId = String(consolidated.conversationId ?? $json.conversationId ?? prev.conversationId ?? docMeta.conversationId ?? '').trim();
const messageId = String(consolidated.messageId ?? $json.messageId ?? prev.messageId ?? Date.now());
const now = Date.now();

// 1. Estado Permanente no PostgreSQL (Persistência no banco de dados)
const pgState = $('Postgres — Consultar Estado Permanente').item?.json ?? {};
const isFirstMessageInPostgres = pgState.is_first_message === true || pgState.greeting_shown === false;
const pgCurrentMode = pgState.current_mode || 'fatec';

// 2. Estado em Memória no Redis (para sessões ativas de submódulos)
let stored = null;
try {
  const raw = $json.appMode;
  stored = typeof raw === 'string' ? JSON.parse(raw) : (raw && typeof raw === 'object' ? raw : null);
} catch { stored = null; }

const validStoredSubmodule = stored && ['agenda', 'cardapio'].includes(stored.app) && typeof stored.sessionKey === 'string' && Number.isFinite(Number(stored.updatedAt)) && (now - Number(stored.updatedAt) >= 0) && (now - Number(stored.updatedAt) <= 15 * 60 * 1000);

const hasAlreadyGreeted = !isFirstMessageInPostgres && Boolean(pgState.greeting_shown || (stored && stored.greeted));

const normText = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9/]+/g, ' ').trim();

// Comandos explícitos de modo
const isCardapioCommand = /^\/cardapio(?:\s|$)/i.test(text) || /^\/menu(?:\s|$)/i.test(text) || /^(cardapio|menu)$/i.test(normText);
const isAgendaCommand = /^\/agenda(?:\s|$)/i.test(text) || /^(agenda|agendamento)$/i.test(normText);
const isCancelCommand = /^\/cancelar(?:\s|$)/i.test(text) || /^(cancelar|parar)$/i.test(normText);
const isClearContextCommand = /^\/(?:limpar_contexto|limparcontexto|limpar|reset|reiniciar)(?:\s|$)/i.test(text) || /^(limpar contexto|limpar conversa|reiniciar conversa|resetar)$/i.test(normText);

const isPureFatecCommand = /^\/fatec\s*$/i.test(text) || /^(fatec|sair|voltar)$/i.test(normText) || /^(atendimento fatec|voltar pra fatec|voltar para fatec|falar com a fatec)$/i.test(normText);
const isFatecWithQuery = /^\/fatec\s+(.+)/i.test(text);

const isGreeting = /^(oi|ola|olá|bom dia|boa tarde|boa noite|e ai|e aí|opa|fala|tudo bem|tudo bom|salve|hello|hi)\b/i.test(text) ||
  /^(oi|ola|olá|bom dia|boa tarde|boa noite|e ai|e aí|opa|fala|tudo bem|tudo bom|salve|hello|hi)$/i.test(normText);

let route = 'rag';
let appSessionKey = null;
let appModeValue = null;
let routedText = text;
const writeMode = (app, sessionKey, greeted = true) => JSON.stringify({ app, sessionKey, greeted, updatedAt: now });

if (isClearContextCommand) {
  route = 'clear_context';
  appModeValue = null;
} else if (isCancelCommand) {
  route = 'cancel';
} else if (isPureFatecCommand) {
  route = 'fatec_welcome';
  appModeValue = writeMode('fatec', null, true);
} else if (isFatecWithQuery) {
  route = 'rag';
  routedText = text.replace(/^\/fatec\s+/i, '').trim();
  appModeValue = writeMode('fatec', null, true);
} else if (isCardapioCommand) {
  route = 'cardapio';
  appSessionKey = 'cardapio:' + conversationId + ':' + now;
  appModeValue = writeMode('cardapio', appSessionKey, true);
} else if (isAgendaCommand) {
  route = 'agenda';
  appSessionKey = 'agenda:' + conversationId + ':' + now;
  appModeValue = writeMode('agenda', appSessionKey, true);
} else if (validStoredSubmodule) {
  route = stored.app;
  appSessionKey = stored.sessionKey;
  appModeValue = writeMode(stored.app, stored.sessionKey, true);
} else if (isFirstMessageInPostgres || (isGreeting && !hasAlreadyGreeted)) {
  // REGRA PERMANENTE NO POSTGRESQL: PRIMEIRA MENSAGEM OU SAUDAÇÃO SEM APRESENTAÇÃO
  route = 'fatec_welcome';
  appModeValue = writeMode('fatec', null, true);
} else {
  route = 'rag';
  appModeValue = writeMode('fatec', null, true);
}

return {
  json: {
    ...prev,
    ...$json,
    contentText: routedText,
    route,
    appSessionKey,
    appModeValue,
    isFirstMessageInPostgres,
    greetingShownInPostgres: Boolean(pgState.greeting_shown)
  }
};

/** Classifica o tipo de entrada (texto, áudio, documento, imagem ou outro) diretamente no fluxo principal. */
const documentExtensions = new Set(['pdf','doc','docx','xls','xlsx','ppt','pptx','txt','csv','rtf','odt','ods']);
const audioExtensions = new Set(['mp3','m4a','ogg','oga','opus','wav','aac','amr','webm']);
const imageExtensions = new Set(['jpg','jpeg','png','webp','gif','heic','bmp','svg']);

return $input.all().map(item => {
  const root = item.json ?? {};
  const payload = root.body ?? root;
  const message = payload.message && typeof payload.message === 'object' ? payload.message : payload;
  const conversation = payload.conversation ?? message.conversation ?? {};
  const recentMessage = Array.isArray(conversation.messages) ? (conversation.messages[0] ?? {}) : {};

  const caption = String(message.content ?? payload.content ?? recentMessage.content ?? payload.caption ?? payload.text ?? '').trim();
  const rawAttachments = Array.isArray(message.attachments) ? message.attachments : Array.isArray(payload.attachments) ? payload.attachments : Array.isArray(recentMessage.attachments) ? recentMessage.attachments : payload.attachment && typeof payload.attachment === 'object' ? [payload.attachment] : [];

  const conversationId = String(conversation.id ?? payload.conversation_id ?? message.conversation_id ?? '');
  const displayId = String(conversation.display_id ?? '');
  const messageId = String(message.id ?? payload.id ?? '');
  const accountId = String(payload.account?.id ?? payload.account_id ?? '');
  const sender = conversation.meta?.sender ?? payload.sender ?? message.sender ?? {};
  const senderPhone = String(sender.phone_number ?? sender.custom_attributes?.waha_whatsapp_chat_id ?? '').replace(/@c\.us$/i, '');
  const senderName = String(sender.name ?? '').trim();

  const attachments = rawAttachments.map(a => {
    const fileType = String(a.file_type ?? a.fileType ?? a.type ?? '').toLowerCase();
    const mimeType = String(a.mime_type ?? a.mimeType ?? a.content_type ?? '').toLowerCase();
    const dataUrl = String(a.data_url ?? a.url ?? a.download_url ?? '');
    const fileName = String(a.file_name ?? a.filename ?? a.name ?? '');
    const urlPath = dataUrl.split(/[?#]/, 1)[0];
    const nameExt = fileName.match(/\.([a-z0-9]{2,8})$/i)?.[1] ?? '';
    const urlExt = urlPath.match(/\.([a-z0-9]{2,8})$/i)?.[1] ?? '';
    const ext = String(a.extension || nameExt || urlExt || '').toLowerCase().replace(/^\./, '');

    const isAudio = fileType === 'audio' || mimeType.startsWith('audio/') || audioExtensions.has(ext);
    const isImage = fileType === 'image' || mimeType.startsWith('image/') || imageExtensions.has(ext);
    const isDoc = fileType === 'file' || fileType === 'document' || mimeType.startsWith('application/') || mimeType.startsWith('text/') || documentExtensions.has(ext);
    const kind = isAudio ? 'audio' : isImage ? 'image' : isDoc ? 'document' : 'unknown';

    return {
      id: String(a.id ?? ''),
      kind,
      fileType,
      mimeType,
      extension: ext,
      fileName,
      dataUrl,
      sizeBytes: a.file_size ?? a.sizeBytes ?? null,
      durationSeconds: a.duration_seconds ?? a.duration ?? a.metadata?.duration_seconds ?? null
    };
  });

  let inputType = 'text';
  let routeIndex = 0; // 0 = Texto, 1 = Audio, 2 = Documento, 3 = Imagem, 4 = NaoSuportado

  if (attachments.length === 0) {
    if (caption) {
      inputType = 'text';
      routeIndex = 0;
    } else {
      inputType = 'unknown';
      routeIndex = 4;
    }
  } else if (attachments.every(a => a.kind === 'audio')) {
    inputType = 'audio';
    routeIndex = 1;
  } else if (attachments.some(a => a.kind === 'document') && !attachments.some(a => a.kind === 'audio')) {
    inputType = 'document';
    routeIndex = 2;
  } else if (attachments.some(a => a.kind === 'image') && !attachments.some(a => a.kind === 'audio')) {
    inputType = 'image';
    routeIndex = 3;
  } else {
    inputType = 'mixed';
    routeIndex = 4;
  }

  const result = {
    ...root,
    accountId,
    conversationId,
    displayId,
    messageId,
    inputType,
    routeIndex,
    caption,
    contentText: caption,
    userTextChars: Array.from(caption).length,
    normalizationStatus: inputType === 'text' ? 'ready' : 'pending',
    senderPhone,
    senderName,
    attachmentCount: attachments.length,
    attachments
  };

  return { json: result };
});

const item = $('Roteador de tipo de mensagem').item.json ?? {};
const binaryData = $binary?.data;

if (!binaryData) {
  return [{ json: { ...item, audioValid: false, audioError: 'Não foi possível baixar o arquivo de áudio enviado.' } }];
}

// 1. Limite de tamanho: 10 MiB
const MAX_BYTES = 10 * 1024 * 1024;
const byteLength = binaryData.fileSize ? Number(binaryData.fileSize) : (binaryData.data ? Buffer.from(binaryData.data, 'base64').length : 0);
if (byteLength > MAX_BYTES) {
  return [{ json: { ...item, audioValid: false, audioError: 'O áudio enviado excede o limite máximo de 10 MB. Envie um arquivo menor ou envie sua mensagem por texto.' } }];
}

// 2. Limite de duração: 60s
let durationSeconds = null;
try {
  const buf = Buffer.from(binaryData.data, 'base64');
  if (buf.length >= 27 && buf.toString('ascii', 0, 4) === 'OggS') {
    let offset = 0, maxGranule = null, preSkip = 0, found = false;
    const unset = 0xffffffffffffffffn;
    while (offset + 27 <= buf.length) {
      if (buf.toString('ascii', offset, offset + 4) !== 'OggS' || buf[offset + 4] !== 0) break;
      const count = buf[offset + 26], table = offset + 27, payload = table + count;
      if (payload > buf.length) break;
      let length = 0;
      for (let i = 0; i < count; i++) length += buf[table + i];
      const end = payload + length;
      if (end > buf.length) break;
      if (!found) {
        const marker = buf.indexOf('OpusHead', payload, 'ascii');
        if (marker >= payload && marker + 12 <= end) { preSkip = buf.readUInt16LE(marker + 10); found = true; }
      }
      const granule = buf.readBigUInt64LE(offset + 6);
      if (granule !== unset && (maxGranule === null || granule > maxGranule)) maxGranule = granule;
      offset = end;
    }
    if (found && maxGranule !== null) {
      const samples = Number(maxGranule) - preSkip;
      if (Number.isFinite(samples) && samples >= 0) durationSeconds = samples / 48000;
    }
  }
} catch (e) {}

if (durationSeconds !== null && durationSeconds > 60) {
  return [{ json: { ...item, audioValid: false, audioError: 'O áudio enviado tem duração superior a 60 segundos. Por favor, envie um áudio mais curto ou digite sua mensagem.' } }];
}

return [{
  json: {
    ...item,
    audioValid: true,
    durationSeconds
  },
  binary: $binary
}];

const prev = $('Validar áudio').item.json ?? {};
const candidates = [$json.text, $json.transcription, $json.transcript, $json.output];
const text = String(candidates.find(v => typeof v === 'string' && v.trim()) ?? '').trim();

if (!text) {
  return [{ json: { ...prev, audioValid: false, normalizationStatus: 'failed', audioError: 'Não foi possível transcrever o áudio enviado ou a fala não estava audível. Por favor, tente enviar novamente ou escreva por texto.' } }];
}

return [{
  json: {
    ...prev,
    contentText: text,
    transcription: text,
    userTextChars: Array.from(text).length,
    normalizationStatus: 'ready'
  }
}];

return {
  json: {
    output: '🏛️ *Assistente Virtual Inteligente*
Projeto de TCC de *Gabriel Bassani da Silva* (Big Data no Agronegócio — Fatec Bebedouro).

Olá! Seja bem-vindo!
Este assistente virtual demonstra uma arquitetura avançada de IA generativa multimodal (texto e voz 24/7). Embora tenha sido desenvolvido com foco inicial na *Fatec Bebedouro* como caso de estudo acadêmico, esta solução é totalmente versátil e personalizável para diversos outros cenários do mercado — como atendimento comercial a clientes, suporte a vendas, pedidos e agendamentos corporativos.

*Comandos e Demonstrações Disponíveis:*
• 🏛️ */fatec:* Atendimento acadêmico (cursos, vestibular, estágio supervisionado e secretaria)
• 🍔 */cardapio:* Atendimento comercial com pedidos, carrinho e registro em planilha (Google Sheets)
• 📅 */agenda:* Agendamento de consultas e serviços com verificação de disponibilidade (Google Calendar)
• ❌ */cancelar:* Cancela um pedido ou agendamento em andamento e retorna ao modo principal

Como posso te ajudar hoje?'
  }
};

return {
  json: {
    output: '*Contexto reiniciado com sucesso!*\n\nComo posso te ajudar hoje?'
  }
};

return (async () => {
  const Redis = require('ioredis');
  const redis = new Redis('redis://:f81a34c353b25e714182ab9345737beec9630d4380d9c6106f34c1afa33a6f8c@redis:6379/0');

  try {
    const item = $input.first()?.json ?? {};
    let convId = String(item.conversationId || item.conversation_id || '');
    if (!convId) {
      try {
        convId = String($('Webhook Chatwoot RAG').first()?.json?.body?.conversation?.id || '');
      } catch (e) {}
    }
    if (convId) {
      const pipeline = redis.pipeline();
      pipeline.set(`chatwoot:last_token:conv:${convId}`, 'cancelled', 'EX', 120);
      pipeline.del(`chatwoot:buffer:conv:${convId}`);
      pipeline.del(`chatwoot:infer_lock:conv:${convId}`);
      pipeline.del(`chatwoot:audio_pending:conv:${convId}`);
      await pipeline.exec();
    }
  } finally {
    redis.disconnect();
  }

  return $input.all();
})();

return (async () => {
  const Redis = require('ioredis');
  const redis = new Redis('redis://:f81a34c353b25e714182ab9345737beec9630d4380d9c6106f34c1afa33a6f8c@redis:6379/0');

  try {
    const item = $input.first()?.json ?? {};
    let convId = String(item.conversationId || item.conversation_id || '');
    if (!convId) {
      try {
        convId = String($('Webhook Chatwoot RAG').first()?.json?.body?.conversation?.id || '');
      } catch (e) {}
    }
    const rateLimitKey = `chatwoot:ratelimit:conv:${convId}`;

    const luaScript = `
      local count = redis.call('INCR', KEYS[1])
      if count == 1 then
        redis.call('EXPIRE', KEYS[1], 30)
      end
      return count
    `;

    const count = await redis.eval(luaScript, 1, rateLimitKey);

    // Da 12ª em diante: descarte silencioso sem alocar nó Wait
    if (count > 11) {
      return [];
    }

    // Na 11ª mensagem: aviso educativo único de bloqueio temporário de 30s e invalidação de pendências
    if (count === 11) {
      const pipeline = redis.pipeline();
      pipeline.set(`chatwoot:last_token:conv:${convId}`, 'rate_limited', 'EX', 120);
      pipeline.del(`chatwoot:buffer:conv:${convId}`);
      pipeline.del(`chatwoot:infer_lock:conv:${convId}`);
      pipeline.del(`chatwoot:audio_pending:conv:${convId}`);
      await pipeline.exec();

      return [{
        json: {
          ...item,
          isRateLimited: true,
          output: 'Você enviou muitas mensagens em um curto intervalo de tempo. Para garantir a estabilidade do atendimento, suas mensagens foram pausadas por 30 segundos. Por favor, aguarde esse período para enviar novas perguntas.'
        }
